/*
 * proc2/test/test_proc2_data.c - the PROC2 module data blocks (source-l2yd)
 *
 * Generated by: Claude Opus 5.5
 *
 * proc2/proc2_data.c is #included, so the objects under test are the real
 * blocks:
 *
 *   PROC2_$WIRED_DATA    map "D E2B978 PROC2_WIRED_ASM size = 690"
 *   PROC2_$UNWIRED_DATA  map "D E7BE84 PROC2 size = 1E8" (A5)
 *   PROC2_$DATA          map "D67 EA551C PROC2_$DATA size = 4168"
 *
 * Checked: the image addresses; the A5 offsets of the unwired block (all
 * host-invariant); the PROC2_$DATA offsets that hold on every build (the
 * absolute ones past info[] are asserted at compile time on the target
 * only, because proc2_info_t is 0xE4 bytes only with 2-byte alignment); the
 * pgroup bias arm over pid_to_index[61..64]; that pid / asid / index N
 * lands where the assembly's `base + N*stride' puts it; the two accessors
 * that apply the element-1 bias (P2_INFO_ENTRY, PROC_FORK_EC /
 * PROC_CR_REC_EC); the image's initial contents (next_upid = 0x41, the rest
 * zero); and, through the real PROC2_$GET_BOOT_FLAGS, that the code reads
 * the block field.
 */

#include <stdint.h>
#include <stdio.h>
#include <string.h>

/* ==========================================================================
 * Test framework
 * ========================================================================== */

static int tests_failed = 0;
static int tests_run = 0;

#define TEST(name) static void test_##name(void)
#define RUN_TEST(name)                                                        \
    do {                                                                      \
        printf("  Running %s... ", #name);                                    \
        tests_run++;                                                          \
        test_##name();                                                        \
        printf("done\n");                                                     \
    } while (0)

#define ASSERT_EQ(expected, actual)                                           \
    do {                                                                      \
        long long _e = (long long)(expected);                                 \
        long long _a = (long long)(actual);                                   \
        if (_e != _a) {                                                       \
            printf("FAILED\n    Expected: 0x%llx, Got: 0x%llx at line %d\n",  \
                   (unsigned long long)_e, (unsigned long long)_a, __LINE__); \
            tests_failed++;                                                   \
            return;                                                           \
        }                                                                     \
    } while (0)

#include "proc2/proc2_internal.h"

#include "../proc2_data.c"
#include "../get_boot_flags.c"

#define OFF(block, field) \
    ((long long)((const uint8_t *)&(block).field - (const uint8_t *)&(block)))

/* ==========================================================================
 * Tests
 * ========================================================================== */

TEST(block_addresses_and_sizes)
{
    ASSERT_EQ(0x00E2B978u, MODULE_DATA_ADDR(PROC2_$WIRED_DATA));
    ASSERT_EQ(0x00E7BE84u, MODULE_DATA_ADDR(PROC2_$UNWIRED_DATA));
    ASSERT_EQ(0x00EA551Cu, MODULE_DATA_ADDR(PROC2_$DATA));
    ASSERT_EQ(0x1E8, sizeof(PROC2_$UNWIRED_DATA));
    /* map symbols inside the unwired block */
    ASSERT_EQ(0x00E7BE94u, MODULE_DATA_ADDR(PROC2_$UNWIRED_DATA) +
                               OFF(PROC2_$UNWIRED_DATA, uid[0]));
    ASSERT_EQ(0x00E7C064u, MODULE_DATA_ADDR(PROC2_$UNWIRED_DATA) +
                               OFF(PROC2_$UNWIRED_DATA, info_alloc_ptr));
    ASSERT_EQ(70, P2_INFO_TABLE_SIZE);
    ASSERT_EQ(70, PROC2_EC_ENTRIES);
}

TEST(unwired_offsets)
{
    ASSERT_EQ(0x000, OFF(PROC2_$UNWIRED_DATA, proc_dir_uid));
    ASSERT_EQ(0x008, OFF(PROC2_$UNWIRED_DATA, system_uid));
    ASSERT_EQ(0x010, OFF(PROC2_$UNWIRED_DATA, uid));
    ASSERT_EQ(0x1E0, OFF(PROC2_$UNWIRED_DATA, info_alloc_ptr));
    ASSERT_EQ(0x1E2, OFF(PROC2_$UNWIRED_DATA, free_list_head));
    ASSERT_EQ(0x1E4, OFF(PROC2_$UNWIRED_DATA, boot_flags));
    ASSERT_EQ(0x1E6, OFF(PROC2_$UNWIRED_DATA, next_upid));
}

/* asid N is uid[N] at A5 + 0x10 + N*8 (0x00E73300..0x00E73308), [0..57] */
TEST(asid_n_is_uid_n)
{
    int asid;
    for (asid = 0; asid < PROC2_UID_TABLE_SIZE; asid++) {
        ASSERT_EQ(0x10 + asid * 8, OFF(PROC2_$UNWIRED_DATA, uid[asid]));
    }
    ASSERT_EQ(0x1E0, OFF(PROC2_$UNWIRED_DATA, uid[PROC2_UID_TABLE_SIZE]));
}

TEST(data_offsets_every_build)
{
    ASSERT_EQ(0, OFF(PROC2_$DATA, info[0]));
    ASSERT_EQ(sizeof(proc2_info_t), OFF(PROC2_$DATA, info[1]));
    /* the pgroup arm overlays pid_to_index from its 0x7A-byte pad */
    ASSERT_EQ(0x7A, OFF(PROC2_$DATA, pgroup[0]) - OFF(PROC2_$DATA, pid_to_index[0]));
    ASSERT_EQ(OFF(PROC2_$DATA, pid_to_index[61]), OFF(PROC2_$DATA, pgroup[0]));
    ASSERT_EQ(OFF(PROC2_$DATA, pid_to_index[65]), OFF(PROC2_$DATA, pgroup[1]));
    /* pgroup[70] ends the block: 0x4168 - 0x3EB6 past pid_to_index[0] */
    ASSERT_EQ(0x4168 - 0x3EB6,
              OFF(PROC2_$DATA, pgroup[PGROUP_TABLE_SIZE]) - OFF(PROC2_$DATA, pid_to_index[0]));
    ASSERT_EQ(OFF(PROC2_$DATA, pgroup[PGROUP_TABLE_SIZE]), sizeof(PROC2_$DATA));
    ASSERT_EQ(0x5E, sizeof(PROC2_$DATA._3e58));
    ASSERT_EQ(OFF(PROC2_$DATA, _3e58) + 0x5E, OFF(PROC2_$DATA, pid_to_index[0]));
}

/* pid N is pid_to_index[N] (0x3eb6 + N*2); index N is pgroup[N]
 * (0x3f30 + N*8); both relative to the table's element 0. */
TEST(pid_and_index_n_are_element_n)
{
    int n;
    for (n = 0; n < PROC1_MAX_PROCESSES; n++) {
        ASSERT_EQ(n * 2, OFF(PROC2_$DATA, pid_to_index[n]) - OFF(PROC2_$DATA, pid_to_index[0]));
    }
    for (n = 0; n < PGROUP_TABLE_SIZE; n++) {
        ASSERT_EQ(0x7A + n * 8, OFF(PROC2_$DATA, pgroup[n]) - OFF(PROC2_$DATA, pid_to_index[0]));
    }
    /* image addresses of the cells PROC2_$INIT names */
    ASSERT_EQ(0x00EA93D4u - 0x00EA93D2u,
              OFF(PROC2_$DATA, pid_to_index[1]) - OFF(PROC2_$DATA, pid_to_index[0]));
    ASSERT_EQ(0x00EA9454u - 0x00EA93D2u,
              OFF(PROC2_$DATA, pgroup[1]) - OFF(PROC2_$DATA, pid_to_index[0]));
}

/* The accessors apply the element-1 bias exactly once. */
TEST(accessors_apply_the_bias_once)
{
    int idx;
    for (idx = 1; idx <= P2_INFO_TABLE_SIZE; idx++) {
        ASSERT_EQ((long long)(idx - 1) * (long long)sizeof(proc2_info_t),
                  (long long)((const uint8_t *)P2_INFO_ENTRY(idx) -
                              (const uint8_t *)&PROC2_$DATA));
        ASSERT_EQ((long long)(intptr_t)&PROC2_$WIRED_DATA.ec[idx - 1].fork_ec,
                  (long long)(intptr_t)PROC_FORK_EC(idx));
        ASSERT_EQ((long long)(intptr_t)&PROC2_$WIRED_DATA.ec[idx - 1].cr_rec_ec,
                  (long long)(intptr_t)PROC_CR_REC_EC(idx));
    }
    ASSERT_EQ((long long)(intptr_t)&PROC2_$WIRED_DATA.ec[0].fork_ec,
              (long long)(intptr_t)&PROC2_$WIRED_DATA);
    /* PTR_PROC2_$DATA (0x00E3238C) is a stored-VA longword: the block's
     * link address on the target, the image's value (00 ea 55 1c) here. */
    ASSERT_EQ(4, sizeof(PTR_PROC2_$DATA));
    ASSERT_EQ(ARCH_PTR_TO_VA_STATIC(&PROC2_$DATA, 0x00EA551C), PTR_PROC2_$DATA);
    ASSERT_EQ(0x00EA551Cu, PTR_PROC2_$DATA);
}

TEST(initial_contents)
{
    size_t i;
    const uint8_t *p;

    ASSERT_EQ(0x41, PROC2_$UNWIRED_DATA.next_upid);
    ASSERT_EQ(P2_UPID_WRAP_TO, PROC2_$UNWIRED_DATA.next_upid);
    p = (const uint8_t *)&PROC2_$UNWIRED_DATA;
    for (i = 0; i < 0x1E6; i++) {
        ASSERT_EQ(0, p[i]);
    }
    p = (const uint8_t *)&PROC2_$DATA;
    for (i = 0; i < sizeof(PROC2_$DATA); i++) {
        ASSERT_EQ(0, p[i]);
    }
    p = (const uint8_t *)&PROC2_$WIRED_DATA;
    for (i = 0; i < sizeof(PROC2_$WIRED_DATA); i++) {
        ASSERT_EQ(0, p[i]);
    }
}

/* PROC2_$GET_BOOT_FLAGS: `move.w (0x1e4,A5),(A0)' (0x00E41B66). */
TEST(get_boot_flags_reads_the_block)
{
    int16_t flags = 0;
    PROC2_$UNWIRED_DATA.boot_flags = 0x1234;
    PROC2_$GET_BOOT_FLAGS(&flags);
    ASSERT_EQ(0x1234, flags);
    PROC2_$UNWIRED_DATA.boot_flags = 0;
}

int main(void)
{
    printf("PROC2 module data tests\n");
    RUN_TEST(block_addresses_and_sizes);
    RUN_TEST(unwired_offsets);
    RUN_TEST(asid_n_is_uid_n);
    RUN_TEST(data_offsets_every_build);
    RUN_TEST(pid_and_index_n_are_element_n);
    RUN_TEST(accessors_apply_the_bias_once);
    RUN_TEST(initial_contents);
    RUN_TEST(get_boot_flags_reads_the_block);
    printf("%d tests, %d failed\n", tests_run, tests_failed);
    return tests_failed ? 1 : 0;
}
